const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const action = text(input.action || 'get').toLowerCase();
const clinic_name = text(input.clinic_name);
const mobile = text(input.mobile);
const consent_type = text(input.consent_type).toLowerCase();
const policy_version = text(input.policy_version);
const expires_at = text(input.expires_at);
const channel = text(input.channel).toLowerCase();
const enabled = bool(input.enabled);
const preferred_language =
  text(input.preferred_language || 'fa').toLowerCase();
const timezone =
  text(input.timezone || 'Asia/Baghdad');
const quiet_hours_enabled =
  bool(input.quiet_hours_enabled);
const quiet_hours_start =
  text(input.quiet_hours_start);
const quiet_hours_end =
  text(input.quiet_hours_end);
const max_messages_per_week =
  Number(input.max_messages_per_week ?? 0);
const actor_name = text(input.actor_name);
const source_channel =
  text(input.source_channel || 'api').toLowerCase();
const reason = text(input.reason);
const confirm_action = bool(input.confirm_action);

let scope_json = input.scope_json ?? {};
let preferences = input.preferences ?? [];

try {
  if (typeof scope_json === 'string') {
    scope_json = JSON.parse(scope_json || '{}');
  }
} catch {
  scope_json = null;
}

try {
  if (typeof preferences === 'string') {
    preferences = JSON.parse(preferences || '[]');
  }
} catch {
  preferences = null;
}

const actions = [
  'get',
  'grant',
  'revoke',
  'set_preference',
  'set_preferences',
];

const consentTypes = [
  'contact',
  'profile_storage',
  'document_storage',
  'appointment_reminders',
  'followup_messages',
  'marketing_messages',
  'satisfaction_surveys',
  'data_processing',
];

const channels = [
  'whatsapp',
  'sms',
  'email',
  'phone',
  'web_push',
  'in_app',
];

const sourceChannels = [
  'web',
  'whatsapp',
  'telegram',
  'sms',
  'email',
  'phone',
  'manual',
  'api',
  'system',
];

const errors = [];

if (!actions.includes(action)) {
  errors.push({
    field: 'action',
    message: 'اقدام معتبر نیست.',
  });
}

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل معتبر نیست.',
  });
}

if (
  ['grant', 'revoke'].includes(action) &&
  !consentTypes.includes(consent_type)
) {
  errors.push({
    field: 'consent_type',
    message: 'نوع رضایت معتبر نیست.',
  });
}

if (
  action === 'set_preference' &&
  !channels.includes(channel)
) {
  errors.push({
    field: 'channel',
    message: 'کانال ارتباطی معتبر نیست.',
  });
}

if (
  !['fa', 'en', 'ar', 'unknown'].includes(
    preferred_language
  )
) {
  errors.push({
    field: 'preferred_language',
    message: 'زبان ترجیحی معتبر نیست.',
  });
}

try {
  new Intl.DateTimeFormat(
    'en-US',
    { timeZone: timezone }
  ).format(new Date());
} catch {
  errors.push({
    field: 'timezone',
    message: 'منطقه زمانی معتبر نیست.',
  });
}

if (
  quiet_hours_enabled &&
  (
    !/^([01]\d|2[0-3]):[0-5]\d$/.test(
      quiet_hours_start
    ) ||
    !/^([01]\d|2[0-3]):[0-5]\d$/.test(
      quiet_hours_end
    )
  )
) {
  errors.push({
    field: 'quiet_hours',
    message: 'ساعت سکوت باید به شکل HH:MM باشد.',
  });
}

if (
  !Number.isInteger(max_messages_per_week) ||
  max_messages_per_week < 0 ||
  max_messages_per_week > 100
) {
  errors.push({
    field: 'max_messages_per_week',
    message: 'حداکثر پیام هفتگی باید بین صفر و 100 باشد.',
  });
}

if (
  !scope_json ||
  Array.isArray(scope_json) ||
  typeof scope_json !== 'object'
) {
  errors.push({
    field: 'scope_json',
    message: 'scope_json باید یک شیء JSON باشد.',
  });
  scope_json = {};
}

if (
  action === 'set_preferences' &&
  (
    !Array.isArray(preferences) ||
    preferences.length < 1 ||
    preferences.length > 20
  )
) {
  errors.push({
    field: 'preferences',
    message: 'preferences باید آرایه‌ای با 1 تا 20 مورد باشد.',
  });
}

if (!Array.isArray(preferences)) {
  preferences = [];
}

for (const item of preferences) {
  if (
    !item ||
    typeof item !== 'object' ||
    !channels.includes(
      text(item.channel).toLowerCase()
    )
  ) {
    errors.push({
      field: 'preferences',
      message: 'حداقل یک ترجیح کانال نامعتبر است.',
    });
    break;
  }
}

if (!actor_name && action !== 'get') {
  errors.push({
    field: 'actor_name',
    message: 'نام انجام‌دهنده الزامی است.',
  });
}

if (!sourceChannels.includes(source_channel)) {
  errors.push({
    field: 'source_channel',
    message: 'کانال منبع معتبر نیست.',
  });
}

if (
  expires_at &&
  Number.isNaN(Date.parse(expires_at))
) {
  errors.push({
    field: 'expires_at',
    message: 'تاریخ انقضا معتبر نیست.',
  });
}

if (
  action !== 'get' &&
  confirm_action !== true
) {
  errors.push({
    field: 'confirm_action',
    message: 'تغییر رضایت یا ترجیح باید تأیید شود.',
  });
}

return [{
  json: {
    action,
    clinic_name,
    mobile,
    consent_type,
    policy_version,
    scope_json_text: JSON.stringify(scope_json),
    expires_at,
    channel,
    enabled,
    preferred_language,
    timezone,
    quiet_hours_enabled,
    quiet_hours_start,
    quiet_hours_end,
    max_messages_per_week,
    preferences_text: JSON.stringify(preferences),
    actor_name,
    source_channel,
    reason,
    confirm_action,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
